const input = $json.body ?? $json;
const requestId = String(input.requestId ?? input.id ?? `${Date.now()}-${Math.random().toString(36).slice(2, 8)}`);
const product = input.product ?? {};
const images = Array.isArray(product.images) ? product.images : [];
const primaryImage = images[0] ?? '';
const dataUrlMatch = primaryImage.match(/^data:([^;]+);base64,(.+)$/s);
const state = $getWorkflowStaticData('global');
state.jobs ??= {};
state.jobs[requestId] = { status: 'processing', createdAt: new Date().toISOString() };
const item = { json: { ...input, ticket_id: requestId, status: 'processing', primaryImage } };
if (dataUrlMatch) {
  item.binary = { reference: { data: dataUrlMatch[2], mimeType: dataUrlMatch[1], fileName: 'reference.jpg' } };
}
return [item];

