const requestId = $('Initialize Job').first().json.ticket_id;
const state = $getWorkflowStaticData('global');
state.jobs ??= {};
const current = state.jobs[requestId] ?? {};

const binaryData = $input.first().binary?.data;
let finalUrl = null;
if (binaryData) {
  finalUrl = `data:${binaryData.mimeType};base64,${binaryData.data}`;
}

state.jobs[requestId] = {
  ...current,
  status: finalUrl ? 'completed' : 'error',
  finalUrl,
  error: finalUrl ? null : 'No image returned.',
  completedAt: new Date().toISOString(),
};
return [{ json: state.jobs[requestId] }];

const ticketId = String($json.query?.ticket_id ?? $json.ticket_id ?? '');
const state = $getWorkflowStaticData('global');
const job = state.jobs?.[ticketId];
return [{ json: job ? { ...job, ticket_id: ticketId } : { status: 'processing', ticket_id: ticketId } }];
